<?php
session_start();
if (isset($_SESSION['user_id'])) { header('Location: Home.php'); exit; }

require_once __DIR__ . '/../DB/conn.php';
require_once __DIR__ . '/includes/account_setup_helper.php';
require_once __DIR__ . '/includes/account_input_validation.php';

$errors = [];
$_SESSION['registration_form_token'] ??= bin2hex(random_bytes(32));
$old = [];
$registration_idnumber = generate_registration_id($conn);
$old['idnumber'] = $registration_idnumber;
function value($key) { return account_input($key); }
function old($key) { global $old; return htmlspecialchars($old[$key] ?? '', ENT_QUOTES, 'UTF-8'); }
function invalid($key) { global $errors; return isset($errors[$key]) ? ' is-invalid' : ''; }
function error_for($key) { global $errors; return isset($errors[$key]) ? '<small class="error">' . htmlspecialchars($errors[$key]) . '</small>' : ''; }

$question_options = [
    'security_q1' => ['What was your first pet\'s name?', 'What is your mother\'s maiden name?', 'What city were you born in?', 'What is your favorite food?', 'What elementary school did you attend?'],
    'security_q2' => ['What was your first car?', 'What is your best friend\'s name?', 'What is your favorite movie?', 'What is your dream job?', 'What is your favorite color?'],
    'security_q3' => ['What is your favorite book?', 'What is your favorite sport?', 'What is your favorite holiday?', 'What is your first teacher\'s name?', 'What is your favorite song?'],
];

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!hash_equals($_SESSION['registration_form_token'], account_input('registration_token', false))) {
        $errors['form'] = 'This registration form expired. Reload the page and try again.';
    }
    $_POST['idnumber'] = $registration_idnumber;
    $fields = ['idnumber','firstname','middlename','lastname','suffix','sex','birth','email','username','street','barangay','municipality','province','postal','security_q1','security_q2','security_q3','security_a1','security_a2','security_a3'];
    foreach ($fields as $field) { $old[$field] = value($field); }
    $required = ['idnumber','firstname','lastname','sex','birth','street','barangay','municipality','province','email','username','passw','cpassword','security_q1','security_q2','security_q3','security_a1','security_a2','security_a3'];
    foreach ($required as $field) { if (value($field) === '') $errors[$field] = 'This field is required.'; }
    if ($old['idnumber'] && !preg_match('/^\d{4}-?\d{4}$/', $old['idnumber'])) $errors['idnumber'] = 'Use the CSU ID format: 1234-5678.';
    foreach (['firstname', 'lastname', 'middlename', 'suffix'] as $field) {
        if ($old[$field] !== '' && !account_name_is_valid($old[$field])) {
            $errors[$field] = 'Use letters, spaces, periods, apostrophes, or hyphens.';
        }
    }
    foreach (['firstname', 'lastname', 'middlename', 'suffix', 'email', 'street', 'barangay', 'municipality', 'province'] as $field) {
        if (!account_text_is_valid($old[$field], 250)) {
            $errors[$field] = 'Use shorter text without control characters.';
        }
    }
    if ($old['postal'] !== '' && !account_postal_is_valid($old['postal'], 'Philippines')) {
        $errors['postal'] = 'Enter a four-digit postal code.';
    }
    if ($old['sex'] !== '' && !in_array($old['sex'], ['Male', 'Female', 'Prefer not to say'], true)) {
        $errors['sex'] = 'Choose an option from the list.';
    }
    $birthDate = preg_match('/^\d{4}-\d{2}-\d{2}$/D', $old['birth']) ? DateTime::createFromFormat('!Y-m-d', $old['birth']) : false;
    if ($old['birth'] && (!$birthDate || $birthDate->format('Y-m-d') !== $old['birth'] || $birthDate > new DateTime())) {
        $errors['birth'] = 'Please enter a valid birthdate.';
    }
    $age = '';
    if (!isset($errors['birth']) && $birthDate) { $age = (new DateTime())->diff($birthDate)->y; if ($age < 10 || $age > 120) $errors['birth'] = 'Please enter a valid birthdate.'; }
    if ($old['email'] && !filter_var($old['email'], FILTER_VALIDATE_EMAIL)) $errors['email'] = 'Please enter a valid email address.';
    if ($old['username'] && !preg_match('/^[A-Za-z0-9_]{4,30}$/', $old['username'])) $errors['username'] = 'Use 4–30 letters, numbers, or underscores.';
    $plainPassword = account_input('passw', false);
    if ($plainPassword !== '' && !account_password_is_valid($plainPassword)) $errors['passw'] = 'Use 8 to 15 characters with uppercase and lowercase letters and a number, without spaces.';
    if ($plainPassword !== account_input('cpassword', false)) $errors['cpassword'] = 'Passwords do not match.';
    foreach (['security_a1', 'security_a2', 'security_a3'] as $field) {
        if (!account_text_is_valid($old[$field], 72)) {
            $errors[$field] = 'Use a shorter answer without control characters (72 bytes maximum).';
        }
    }
    foreach ($question_options as $field => $options) {
        if ($old[$field] !== '' && !in_array($old[$field], $options, true)) {
            $errors[$field] = 'Choose a question from the list.';
        }
    }
    if (count(array_unique([$old['security_q1'],$old['security_q2'],$old['security_q3']])) !== 3) $errors['security_q1'] = 'Please select three different questions.';
    if (!isset($_POST['terms'])) $errors['terms'] = 'Please accept the Terms and Conditions to continue.';

    if (!$errors) {
        if (!$conn) { $errors['form'] = 'Connection failed. Please try again later.'; }
        else {
            // Server-side enforcement: client checks are only a convenience and can be bypassed.
            $id_check = $conn->prepare('SELECT 1 FROM infos WHERE idnumber = ? LIMIT 1');
            if ($id_check) {
                $id_check->bind_param('s', $old['idnumber']);
                $id_check->execute();
                $id_check->store_result();
                if ($id_check->num_rows > 0) $errors['idnumber'] = 'This ID number is already registered.';
                $id_check->close();
            }
            // Check both account identifiers before inserting so the user gets
            // a clear error beside the field that is already in use.
            if (!$errors) {
                $account_check = $conn->prepare('SELECT email, username FROM infos WHERE email = ? OR username = ?');
                if (!$account_check) {
                    $errors['form'] = 'Database error. Please try again later.';
                } else {
                    $account_check->bind_param('ss', $old['email'], $old['username']);
                    $account_check->execute();
                    $account_result = $account_check->get_result();
                    while ($account = $account_result->fetch_assoc()) {
                        if (strcasecmp($account['email'], $old['email']) === 0) $errors['email'] = 'This email is already registered.';
                        if (strcasecmp($account['username'], $old['username']) === 0) $errors['username'] = 'This username is already taken.';
                    }
                    $account_check->close();
                }
            }
            if (!$errors) {
            $password = password_hash($plainPassword, PASSWORD_BCRYPT);
            $security_a1_hash = password_hash($old['security_a1'], PASSWORD_BCRYPT);
            $security_a2_hash = password_hash($old['security_a2'], PASSWORD_BCRYPT);
            $security_a3_hash = password_hash($old['security_a3'], PASSWORD_BCRYPT);
            $country = 'Philippines'; $role = 'customer'; $status = 'pending';
            $stmt = $conn->prepare('INSERT INTO infos (idnumber, firstname, lastname, middlename, suffix, sex, age, birth, email, username, passw, street, barangay, municipality, province, postal, country, security_q1, security_a1, security_q2, security_a2, security_q3, security_a3, role, status, approved) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0)');
            if (!$stmt) { $errors['form'] = 'Database error. Please try again later.'; }
            else {
                $stmt->bind_param(str_repeat('s', 25), $old['idnumber'], $old['firstname'], $old['lastname'], $old['middlename'], $old['suffix'], $old['sex'], $age, $old['birth'], $old['email'], $old['username'], $password, $old['street'], $old['barangay'], $old['municipality'], $old['province'], $old['postal'], $country, $old['security_q1'], $security_a1_hash, $old['security_q2'], $security_a2_hash, $old['security_q3'], $security_a3_hash, $role, $status);
                $conn->begin_transaction();
                try {
                    if ($stmt->execute()) {
                        $new_user_id = $conn->insert_id;
                        $pending = $conn->prepare("INSERT INTO pending_approvals (user_id, username, full_name, email, status) VALUES (?, ?, ?, ?, 'pending')");
                        if ($pending) { $full_name = trim($old['firstname'] . ' ' . ($old['middlename'] ? $old['middlename'] . '. ' : '') . $old['lastname'] . ($old['suffix'] ? ' ' . $old['suffix'] : '')); $pending->bind_param('isss', $new_user_id, $old['username'], $full_name, $old['email']); $pending->execute(); }
                        $log = $conn->prepare("INSERT INTO user_activity_logs (user_id, activity_type, activity_details, ip_address, user_agent) VALUES (?, 'register', 'New customer registered - pending approval', ?, ?)");
                        if ($log) { $ip = $_SERVER['REMOTE_ADDR'] ?? ''; $agent = $_SERVER['HTTP_USER_AGENT'] ?? ''; $log->bind_param('iss', $new_user_id, $ip, $agent); $log->execute(); }
                        $conn->commit();
                        unset($_SESSION['registration_form_token']);
                        $_SESSION['registration_pending'] = true;
                        header('Location: Sign_in.php', true, 303);
                        exit;
                    }
                    $conn->rollback();
                    $errors['form'] = 'Unable to create the account. Please try again.';
                } catch (mysqli_sql_exception $e) {
                    $conn->rollback();
                    $message = strtolower($e->getMessage());
                    $errors['form'] = str_contains($message, 'email') ? 'This email is already registered.' : (str_contains($message, 'username') ? 'This username is already taken.' : 'This account already exists or could not be created.');
                }
                $stmt->close();
            }
            }
        }
    }
}
?>
