<style>
:root{--green:#0b563a;--dark:#073d2a;--gold:#d9b64a;--ink:#173229;--muted:#66756e;--line:#dce6e0;--mist:#f4f7f5;--error:#b42318}*{box-sizing:border-box}body{margin:0;background:var(--mist);color:var(--ink);font:15px 'DM Sans',Arial,sans-serif;line-height:1.45}a{text-decoration:none;color:inherit}.nav{height:74px;background:#fff;border-bottom:1px solid var(--line)}.nav-in{width:min(1100px,calc(100% - 32px));height:100%;margin:auto;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:10px;font-size:14px;font-weight:700}.brand img{width:44px;height:44px;object-fit:contain}.brand small{display:block;color:var(--muted);font-size:11px;font-weight:500}.login{color:var(--green);font-weight:700;font-size:14px}.page{padding:42px 16px 60px}.card{width:min(850px,100%);margin:auto;background:#fff;border:1px solid var(--line);border-radius:18px;box-shadow:0 13px 35px rgba(20,64,43,.08);overflow:hidden}.card-head{text-align:center;padding:30px 35px 21px;border-bottom:1px solid var(--line)}.card-head img{width:54px;height:54px;object-fit:contain}.card-head h1{margin:8px 0 3px;font-size:27px;letter-spacing:-.035em}.card-head p{margin:0;color:var(--muted)}.progress{display:grid;grid-template-columns:repeat(4,1fr);gap:0;margin:27px auto 0;max-width:680px}.progress button{border:0;background:none;padding:0 4px;color:#87958e;font:600 12px inherit;cursor:default}.progress button.can-go{cursor:pointer}.bubble{width:29px;height:29px;margin:0 auto 6px;display:grid;place-items:center;border:1px solid #cad8d0;border-radius:50%;background:#fff}.progress button.active,.progress button.done{color:var(--green)}.progress button.active .bubble{background:var(--green);border-color:var(--green);color:#fff}.progress button.done .bubble{background:#e2efe6;border-color:#a8c9b4}.form{padding:31px 45px 39px}.step{display:none;animation:appear .25s ease}.step.active{display:block}@keyframes appear{from{opacity:0;transform:translateX(10px)}to{opacity:1;transform:none}}.step-tag{color:var(--green);font-size:12px;font-weight:700;letter-spacing:.08em;text-transform:uppercase}.step h2{margin:4px 0 5px;font-size:22px;letter-spacing:-.025em}.lead{margin:0 0 25px;color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}.grid.three{grid-template-columns:repeat(3,1fr)}.field.full{grid-column:1/-1}label{display:block;margin:0 0 6px;font-size:13px;font-weight:700}label b{color:var(--error)}input,select,textarea{width:100%;padding:11px 12px;border:1px solid #cbd8d1;border-radius:8px;background:#fff;color:var(--ink);font:inherit;outline:0;transition:border .2s,box-shadow .2s}textarea{min-height:82px;resize:vertical}input:focus,select:focus,textarea:focus{border-color:var(--green);box-shadow:0 0 0 3px rgba(11,86,58,.12)}.password-wrap{position:relative}.password-wrap input{padding-right:45px}.password-toggle{position:absolute;right:7px;top:50%;transform:translateY(-50%);border:0;background:transparent;padding:7px;cursor:pointer;font-size:17px;line-height:1}.password-toggle:focus-visible{outline:2px solid var(--green);border-radius:5px}.is-invalid{border-color:var(--error)}.error{display:block;margin-top:5px;color:var(--error);font-weight:600}.hint{margin:5px 0 0;color:var(--muted);font-size:12px}.actions{display:flex;justify-content:space-between;gap:12px;margin-top:30px;padding-top:20px;border-top:1px solid var(--line)}.actions.end{justify-content:flex-end}.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;border:1px solid transparent;border-radius:8px;padding:12px 17px;background:var(--green);color:#fff;font:700 14px inherit;cursor:pointer;transition:.2s}.btn:hover{background:var(--dark);transform:translateY(-1px)}.btn.secondary{background:#fff;border-color:#bcd1c4;color:var(--green)}.btn.secondary:hover{background:#f2f8f4}.notice{margin-bottom:22px;padding:11px 13px;border-radius:8px;background:#fff0ef;color:var(--error);border:1px solid #f4c7c3;font-weight:600}.checks{display:grid;gap:13px}.check{display:flex;gap:10px;align-items:flex-start;padding:13px;border:1px solid var(--line);border-radius:9px}.check input{width:17px;height:17px;margin:2px 0 0;accent-color:var(--green)}.terms a{color:var(--green);font-weight:700;text-decoration:underline}.foot{text-align:center;padding:18px;color:#829089;font-size:12px}@media(max-width:620px){.nav{height:67px}.brand img{width:38px;height:38px}.brand{font-size:12px}.page{padding:22px 11px 40px}.card-head{padding:24px 13px 17px}.form{padding:26px 20px 30px}.progress button{font-size:10px}.bubble{width:26px;height:26px}.grid,.grid.three{grid-template-columns:1fr}.field.full{grid-column:auto}.actions{margin-top:24px}}
</style></head><body>
<header class="nav"><div class="nav-in"><a class="brand" href="home_.php"><img src="../PICTURES/Site-Logo.png" alt="CSUCC logo"><span>Caraga State University – Cabadbaran Campus<small>Lost &amp; Found Management System</small></span></a><a class="login" href="Sign_in.php">Sign in</a></div></header>
<main class="page"><section class="card"><div class="card-head"><img src="../PICTURES/Site-Logo.png" alt="CSUCC FIND"><h1>Create Account</h1><p>Complete your registration step by step</p><div class="progress" aria-label="Registration progress"><button type="button" data-step="1"><span class="bubble">1</span>Personal Info</button><button type="button" data-step="2"><span class="bubble">2</span>Address</button><button type="button" data-step="3"><span class="bubble">3</span>Account</button><button type="button" data-step="4"><span class="bubble">4</span>Security</button></div></div>
<form class="form" method="post" id="registrationForm" novalidate><input type="hidden" name="registration_token" value="<?= htmlspecialchars($_SESSION['registration_form_token']) ?>"><?php if (isset($errors['form'])) echo '<div class="notice">' . htmlspecialchars($errors['form']) . '</div>'; ?>
<section class="step" data-step="1"><div class="step-tag">Step 1 of 4</div><h2>Personal Information</h2><p class="lead">Tell us a little about yourself.</p><div class="grid three"><div class="field"><label for="idnumber">ID Number <b>*</b></label><input class="<?= invalid('idnumber') ?>" id="idnumber" name="idnumber" value="<?= old('idnumber') ?>" inputmode="numeric" maxlength="9" placeholder="1234-5678" required><?= error_for('idnumber') ?></div><div class="field"><label for="firstname">First Name <b>*</b></label><input class="<?= invalid('firstname') ?>" id="firstname" name="firstname" maxlength="250" value="<?= old('firstname') ?>" autocomplete="given-name" required><?= error_for('firstname') ?></div><div class="field"><label for="middlename">M.I.</label><input class="<?= invalid('middlename') ?>" id="middlename" name="middlename" maxlength="250" value="<?= old('middlename') ?>" maxlength="20"><?= error_for('middlename') ?></div><div class="field"><label for="lastname">Last Name <b>*</b></label><input class="<?= invalid('lastname') ?>" id="lastname" name="lastname" maxlength="250" value="<?= old('lastname') ?>" autocomplete="family-name" required><?= error_for('lastname') ?></div><div class="field"><label for="suffix">Extension</label><input class="<?= invalid('suffix') ?>" id="suffix" name="suffix" maxlength="250" value="<?= old('suffix') ?>" placeholder="Jr., Sr., III"><?= error_for('suffix') ?></div><div class="field"><label for="sex">Sex <b>*</b></label><select class="<?= invalid('sex') ?>" id="sex" name="sex" required><option value="">Select sex</option><option value="Male" <?= old('sex')==='Male'?'selected':'' ?>>Male</option><option value="Female" <?= old('sex')==='Female'?'selected':'' ?>>Female</option><option value="Prefer not to say" <?= old('sex')==='Prefer not to say'?'selected':'' ?>>Prefer not to say</option></select><?= error_for('sex') ?></div><div class="field"><label for="birth">Birthdate <b>*</b></label><input class="<?= invalid('birth') ?>" type="date" id="birth" name="birth" value="<?= old('birth') ?>" required><?= error_for('birth') ?></div><div class="field"><label for="age">Age</label><input id="age" name="age_display" readonly aria-readonly="true" value=""><p class="hint">Calculated from birthdate</p></div></div><div class="actions end"><button class="btn" type="button" data-next>Next <span>→</span></button></div></section>
<section class="step" data-step="2"><div class="step-tag">Step 2 of 4</div><h2>Address</h2><p class="lead">Where can campus staff reach you if needed?</p><div class="grid"><div class="field"><label for="barangay">Barangay <b>*</b></label><input class="<?= invalid('barangay') ?>" id="barangay" name="barangay" maxlength="250" value="<?= old('barangay') ?>" required><?= error_for('barangay') ?></div><div class="field"><label for="municipality">Municipality/City <b>*</b></label><input class="<?= invalid('municipality') ?>" id="municipality" name="municipality" maxlength="250" value="<?= old('municipality') ?>" required><?= error_for('municipality') ?></div><div class="field"><label for="province">Province <b>*</b></label><input class="<?= invalid('province') ?>" id="province" name="province" maxlength="250" value="<?= old('province') ?>" required><?= error_for('province') ?></div><div class="field"><label for="postal">Postal Code</label><input id="postal" name="postal" maxlength="4" value="<?= old('postal') ?>" inputmode="numeric"><?= error_for('postal') ?></div><div class="field full"><label for="street">Complete Address <b>*</b></label><textarea class="<?= invalid('street') ?>" id="street" name="street" maxlength="250" required><?= old('street') ?></textarea><?= error_for('street') ?></div></div><div class="actions"><button class="btn secondary" type="button" data-back>← Back</button><button class="btn" type="button" data-next>Next →</button></div></section>
<section class="step" data-step="3"><div class="step-tag">Step 3 of 4</div><h2>Account Details</h2><p class="lead">Choose credentials for your CSUCC FIND account.</p><div class="grid"><div class="field"><label for="email">Email Address <b>*</b></label><input class="<?= invalid('email') ?>" type="email" id="email" name="email" maxlength="250" value="<?= old('email') ?>" autocomplete="email" required><?= error_for('email') ?></div><div class="field"><label for="username">Username <b>*</b></label><input class="<?= invalid('username') ?>" id="username" name="username" maxlength="30" value="<?= old('username') ?>" autocomplete="username" required><?= error_for('username') ?><p class="hint">4–30 letters, numbers, or underscores</p></div><div class="field"><label for="passw">Password <b>*</b></label><div class="password-wrap"><input class="<?= invalid('passw') ?>" type="password" id="passw" name="passw" maxlength="15" autocomplete="new-password" required><button class="password-toggle" type="button" data-toggle-password="passw" aria-label="Show password" aria-pressed="false">👁</button></div><?= error_for('passw') ?><p class="hint">8 to 15 characters, uppercase, lowercase, and a number</p></div><div class="field"><label for="cpassword">Confirm Password <b>*</b></label><div class="password-wrap"><input class="<?= invalid('cpassword') ?>" type="password" id="cpassword" name="cpassword" maxlength="15" autocomplete="new-password" required><button class="password-toggle" type="button" data-toggle-password="cpassword" aria-label="Show password" aria-pressed="false">👁</button></div><?= error_for('cpassword') ?></div></div><div class="actions"><button class="btn secondary" type="button" data-back>← Back</button><button class="btn" type="button" data-next>Next →</button></div></section>
<section class="step" data-step="4"><div class="step-tag">Step 4 of 4</div><h2>Security</h2><p class="lead">Security questions help protect your account and recover access.</p><div class="grid three"><div class="field"><label for="security_q1">Security Question 1 <b>*</b></label><select class="<?= invalid('security_q1') ?>" id="security_q1" name="security_q1" required><option value="">Select a question</option><?php foreach ($question_options['security_q1'] as $question): ?><option <?= ($old['security_q1'] ?? '') === $question ? 'selected' : '' ?>><?= htmlspecialchars($question, ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select><?= error_for('security_q1') ?></div><div class="field"><label for="security_q2">Security Question 2 <b>*</b></label><select id="security_q2" name="security_q2" required><option value="">Select a question</option><?php foreach ($question_options['security_q2'] as $question): ?><option <?= ($old['security_q2'] ?? '') === $question ? 'selected' : '' ?>><?= htmlspecialchars($question, ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select><?= error_for('security_q2') ?><?= error_for('security_q2') ?></div><div class="field"><label for="security_q3">Security Question 3 <b>*</b></label><select id="security_q3" name="security_q3" required><option value="">Select a question</option><?php foreach ($question_options['security_q3'] as $question): ?><option <?= ($old['security_q3'] ?? '') === $question ? 'selected' : '' ?>><?= htmlspecialchars($question, ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select><?= error_for('security_q3') ?><?= error_for('security_q3') ?></div><div class="field"><label for="security_a1">Answer 1 <b>*</b></label><div class="password-wrap"><input type="password" id="security_a1" name="security_a1" maxlength="72" required><button class="password-toggle" type="button" data-toggle-password="security_a1" aria-label="Show security answer 1" aria-pressed="false">👁</button></div><?= error_for('security_a1') ?></div><div class="field"><label for="security_a2">Answer 2 <b>*</b></label><div class="password-wrap"><input type="password" id="security_a2" name="security_a2" maxlength="72" required><button class="password-toggle" type="button" data-toggle-password="security_a2" aria-label="Show security answer 2" aria-pressed="false">👁</button></div><?= error_for('security_a2') ?></div><div class="field"><label for="security_a3">Answer 3 <b>*</b></label><div class="password-wrap"><input type="password" id="security_a3" name="security_a3" maxlength="72" required><button class="password-toggle" type="button" data-toggle-password="security_a3" aria-label="Show security answer 3" aria-pressed="false">👁</button></div><?= error_for('security_a3') ?></div></div><div class="checks"><label class="check terms"><input type="checkbox" id="terms" name="terms" <?= isset($_POST['terms'])?'checked':'' ?> required><span>I agree to the <a href="#terms">Terms and Conditions</a> and understand my account requires approval.</span></label><?= error_for('terms') ?></div><div class="actions"><button class="btn secondary" type="button" data-back>← Back</button><button class="btn" type="submit">Create Account →</button></div></section></form></section><div class="foot">© 2026 CSUCC FIND · Caraga State University – Cabadbaran Campus</div></main>
<script>
const form=document.getElementById('registrationForm'), steps=[...document.querySelectorAll('.step')], dots=[...document.querySelectorAll('.progress button')],savedSecurity=<?= json_encode(['security_q1' => $old['security_q1'] ?? '', 'security_q2' => $old['security_q2'] ?? '', 'security_q3' => $old['security_q3'] ?? ''], JSON_HEX_TAG | JSON_HEX_APOS | JSON_HEX_AMP | JSON_HEX_QUOT) ?>;Object.entries(savedSecurity).forEach(([id,value])=>document.getElementById(id).value=value);let current=1,complete=0;
document.querySelectorAll('[data-toggle-password]').forEach(button=>button.addEventListener('click',()=>{const input=document.getElementById(button.dataset.togglePassword),showing=input.type==='text';input.type=showing?'password':'text';button.setAttribute('aria-pressed',String(!showing));button.setAttribute('aria-label',showing?'Show password':'Hide password')}));
const message=(field,text)=>{field.classList.add('is-invalid');let e=field.parentElement.querySelector('.js-error');if(!e){e=document.createElement('small');e.className='error js-error';field.parentElement.append(e)}e.textContent=text};const clear=field=>{field.classList.remove('is-invalid');field.parentElement.querySelector('.js-error')?.remove()};
let idCheckVersion=0;async function checkIdAvailability(){const field=document.getElementById('idnumber'),id=field.value,version=++idCheckVersion;if(!/^\d{4}-?\d{4}$/.test(id))return false;try{const response=await fetch('check_id_number.php?idnumber='+encodeURIComponent(id),{headers:{Accept:'application/json'}}),data=await response.json();if(version!==idCheckVersion||field.value!==id)return false;clear(field);if(data.exists){message(field,'This ID number is already registered.');field.focus();return true}}catch(error){console.warn('ID availability check could not be completed.',error)}return false}async function checkAccountAvailability(){const fields=[['email','This email is already registered.'],['username','This username is already taken.']];const results=await Promise.all(fields.map(async([type,text])=>{const field=document.getElementById(type);if(!field.value||!field.validity.valid)return false;try{const response=await fetch('check_'+type+'.php?'+type+'='+encodeURIComponent(field.value),{headers:{Accept:'application/json'}}),data=await response.json();clear(field);if(data.exists){message(field,text);return true}}catch(error){console.warn('Account availability check could not be completed.',error)}return false}));return results.some(Boolean)}async function validate(step){let valid=true,first;const fields=steps[step-1].querySelectorAll('input,select,textarea');fields.forEach(f=>{clear(f);let text='';if(f.type==='checkbox'&&!f.checked)text='Please accept the Terms and Conditions to continue.';else if(!f.value.trim()&&f.required)text='This field is required.';else if(!f.value.trim())return;else if(f.id==='idnumber'&&!/^\d{4}-?\d{4}$/.test(f.value))text='Use the CSU ID format: 1234-5678.';else if(['firstname','lastname','middlename','suffix'].includes(f.id)&&!/^(?=.*\p{L})[\p{L}\p{M} .?'-]+$/u.test(f.value))text='Please enter valid name characters.';else if(f.id==='postal'&&!/^\d{4}$/.test(f.value))text='Enter a four-digit postal code.';else if(f.type==='email'&&!f.validity.valid)text='Please enter a valid email address.';else if(f.id==='username'&&!/^[A-Za-z0-9_]{4,30}$/.test(f.value))text='Use 4–30 letters, numbers, or underscores.';else if(f.id==='passw'&&!/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)[!-~]{8,15}$/.test(f.value))text='Use 8 to 15 characters with uppercase, lowercase, and a number.';else if(f.id==='cpassword'&&f.value!==document.getElementById('passw').value)text='Passwords do not match.';if(text){valid=false;message(f,text);first??=f}});if(valid&&step===1&&await checkIdAvailability()){valid=false;first=document.getElementById('idnumber')}if(valid&&step===3&&await checkAccountAvailability()){valid=false;first=document.querySelector('#email.is-invalid,#username.is-invalid')}if(step===4){const q=['security_q1','security_q2','security_q3'].map(id=>document.getElementById(id).value);if(new Set(q).size!==3){valid=false;message(document.getElementById('security_q1'),'Please select three different questions.');first??=document.getElementById('security_q1')}}if(!valid){first.focus();first.scrollIntoView({behavior:'smooth',block:'center'})}return valid}
function show(n){current=n;steps.forEach((s,i)=>s.classList.toggle('active',i===n-1));dots.forEach((d,i)=>{d.className=(i+1===n?'active ':i+1<=complete?'done can-go':'');d.disabled=i+1>complete});window.scrollTo({top:0,behavior:'smooth'})}document.querySelectorAll('[data-next]').forEach(b=>b.onclick=async()=>{if(await validate(current)){complete=Math.max(complete,current);show(current+1)}});document.querySelectorAll('[data-back]').forEach(b=>b.onclick=()=>show(current-1));dots.forEach(d=>d.onclick=()=>{let n=+d.dataset.step;if(n<=complete)show(n)});document.getElementById('birth').onchange=e=>{let d=new Date(e.target.value),now=new Date(),age=now.getFullYear()-d.getFullYear(),m=now.getMonth()-d.getMonth();if(m<0||(m===0&&now.getDate()<d.getDate()))age--;document.getElementById('age').value=isNaN(age)||age<0?'':age};document.getElementById('idnumber').oninput=e=>{let v=e.target.value.replace(/\D/g,'').slice(0,8);e.target.value=v.length>4?v.slice(0,4)+'-'+v.slice(4):v;idCheckVersion++;clear(e.target)};document.getElementById('idnumber').addEventListener('blur',()=>checkIdAvailability());['email','username'].forEach(id=>{const field=document.getElementById(id);field.addEventListener('input',()=>clear(field));field.addEventListener('blur',()=>checkAccountAvailability())});form.addEventListener('submit',async e=>{e.preventDefault();if(!await validate(4))return;let b=form.querySelector('[type=submit]');b.disabled=true;b.textContent='Creating account…';form.submit()});show(<?= $errors ? (isset($errors['idnumber'])||isset($errors['firstname'])||isset($errors['lastname'])||isset($errors['sex'])||isset($errors['birth'])?1:(isset($errors['street'])||isset($errors['barangay'])||isset($errors['municipality'])||isset($errors['province'])?2:(isset($errors['email'])||isset($errors['username'])||isset($errors['passw'])||isset($errors['cpassword'])?3:4))) : 1 ?>);
</script><script>document.getElementById('idnumber').readOnly=true;document.getElementById('idnumber').setAttribute('aria-readonly','true');</script></body></html>
